#include<bits/stdc++.h>
using namespace std;
class PhanSo{
	private:
		int ts;
		int ms;
	public:
		PhanSo(){
			this->ts = 0;
			this->ms = 0;
		}
		PhanSo(int ts,int ms){
			this->ts = ts;
			this->ms = ms;
		}
		void Rutgon(){
			int g = gcd(this->ts, this->ms);
			this->ts = this->ts / g;
			this->ms = this->ms / g;
		}
		bool operator == (const PhanSo &t)const{
			return ts == t.ts && ms == t.ms;
		}
		friend istream &operator >> (istream &is,PhanSo &t){
			cout<<"Nhap phan so";
			is>>t.ts>>t.ms;
			return is;
		}
};
int main(){
	PhanSo *ps1 = new PhanSo(3,4);
	PhanSo *ps2 = new PhanSo();
	cin>>ps2;
	ps1.Rutgon();
	ps2.Rutgon();
	if(ps1 == ps2){
		cout<<"Bang nhau"<<endl;
	}else{
		cout<<"Khong bang nhau"<<endl;
	}
	return 0;
}
